const probe = String.raw`
import * as observeProbePort from "../repository/git-landing-port.js";
import { vi as observeProbeVi } from "vitest";
it("ARCHITECT_OBSERVE_TRANSIENT retains the reservation for retry", async () => {
  const createPort = observeProbePort.createGitLandingPort;
  let armed = false;
  let failures = 0;
  const spy = observeProbeVi.spyOn(observeProbePort, "createGitLandingPort")
    .mockImplementation((runner) => createPort(async (cwd, args, stdin) => {
      if (armed && args[0] === "status") {
        failures += 1;
        return { code: 1, stderr: "OBSERVE_TRANSIENT_PROBE", stdout: "" };
      }
      return (runner ?? observeProbePort.nodeGitRunner)(cwd, args, stdin);
    }));
  const f = fixture();
  try {
    const started = await f.runtime.start(async () => ({
      ok: true, pid: process.pid, exit: Promise.resolve()
    }))(f.request("a"));
    if (!started.ok) throw new Error(started.code);
    await started.exit;
    writeFileSync(join(f.workspace, "keep.txt"), "after\\n");
    f.submit("a"); f.retire(); f.disableLanding();
    await f.runtime.advance();
    expect(readRepositoryDeliveryFacts(f.store, f.projectId, "a")).toBe("ACCEPTED");
    const version = f.store.getAggregateVersion(landingAggregateId("a"));
    armed = true; f.enableLanding(); await f.runtime.advance();
    expect(failures).toBe(1);
    expect(f.logs).toContain("[lander] a: GIT_FAILED (OBSERVE_TRANSIENT_PROBE)");
    expect(readRepositoryDeliveryFacts(f.store, f.projectId, "a")).toBe("ACCEPTED");
    expect(f.store.getAggregateVersion(landingAggregateId("a"))).toBe(version);
    expect(createRepositoryExecutionPort().inspect(f.workspace))
      .toMatchObject({ ok: true, reservation: { nodeRef:"a",phase:"AWAITING_LANDING" } });
    armed = false; await f.runtime.advance();
    expect(readRepositoryDeliveryFacts(f.store, f.projectId, "a")).toBe("LANDED");
  } finally { spy.mockRestore(); await f.runtime.close(); }
}, 120000);
`;
export default {plugins:[{
 name:"architect-observe-probe", enforce:"pre",
 transform(code,id) {
  if(id.replaceAll("\\\\","/").split("?")[0]
    .endsWith("/src/orchestrator/repository-delivery-runtime.test.ts")) {
    return {code:code+"\\n"+probe,map:null};
  }
 }
}]};

Scope clarification asked in REPL: retain existing unbounded one-attempt-per-advance retry, no retry-budget feature or repair of already-BLOCKED reservations. Awaiting human confirmation before submit_plan.

