// Process-local mutation drill for task-65a594816ed5460f999fbd46f40c5cea.
const NEEDLE = '\n        || report.outcome === "GIT_FAILED"';
const TARGET = "/src/orchestrator/repository-delivery-runtime.ts";

export default {
  plugins: [{
    name: "observe-retry-mutant",
    enforce: "pre",
    transform(code, id) {
      const path = id.replaceAll("\\", "/").split("?")[0];
      if (!path.endsWith(TARGET)) return;
      const matches = code.split(NEEDLE).length - 1;
      if (matches !== 1) {
        throw new Error(`MUTANT_GUARD: expected exactly 1 match of the new disjunct, found ${matches}`);
      }
      const mutated = code.replace(NEEDLE, "");
      if (!mutated.includes('landingVerificationClass(report.outcome) === "TRANSIENT"')
        || !mutated.includes('report.outcome === "GIT_INDEX_LOCKED"')) {
        throw new Error("MUTANT_GUARD: the parent's TRANSIENT branch or the index-lock branch was dropped");
      }
      return { code: mutated, map: null };
    },
  }],
};

